// export every row as newline-delimited JSON (one beacon_log per line)
inline bool export_json(::harpia::db::beacon_log_dao& dao, std::string* out) {
    std::vector<::beacon_log> rows;
    if (!dao.list(&rows)) return false;
    out->clear();
    for (const auto& r : rows) {
        std::string j;
        if (!::harpia::json::to_json(r, &j)) return false;
        *out += j;
        *out += "\n";
    }
    return true;
}

// import newline-delimited JSON into the table (one beacon_log per line)
inline bool import_json(::harpia::db::beacon_log_dao& dao, const std::string& ndjson) {
    std::istringstream ss(ndjson);
    std::string line;
    while (std::getline(ss, line)) {
        if (line.empty()) continue;
        ::beacon_log msg;
        if (!::harpia::json::from_json(line, &msg)) return false;
        if (!dao.create(msg)) return false;
    }
    return true;
}

// export every row as <beacon_log_list> ... </beacon_log_list>
inline bool export_xml(::harpia::db::beacon_log_dao& dao, std::string* out) {
    std::vector<::beacon_log> rows;
    if (!dao.list(&rows)) return false;
    *out = "<beacon_log_list>";
    for (const auto& r : rows) *out += ::harpia::xml::to_xml(r);
    *out += "</beacon_log_list>";
    return true;
}

// import <beacon_log_list> ... </beacon_log_list> into the table
inline bool import_xml(::harpia::db::beacon_log_dao& dao, const std::string& xml) {
    ::tinyxml2::XMLDocument doc;
    if (doc.Parse(xml.c_str()) != ::tinyxml2::XML_SUCCESS) return false;
    const auto* root = doc.RootElement();
    if (!root) return false;
    for (const auto* el = root->FirstChildElement(); el;
         el = el->NextSiblingElement()) {
        ::beacon_log msg;
        if (!::harpia::xml::from_xml_element(el, &msg)) return false;
        if (!dao.create(msg)) return false;
    }
    return true;
}

